contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function holding the test
    function run(address[] calldata _tos, uint[] calldata v) public payable {
        require(true);

        // observe public getters before the call
        address before_from = c.from();
        address before_caddress = c.caddress();

        // perform the call and capture whether it reverted
        bool reverted;
        bool ret;
        // transfer is not view, so call it top-level
        try c.transfer(_tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // observe public getters after the call
        address after_from = c.from();
        address after_caddress = c.caddress();

        // General rule:
        // - c.from and c.caddress must never change as a result of transfer
        // - if the call did not revert then it must have returned true
        // - if called with empty _tos it must revert
        assert(
            after_from == before_from
            && after_caddress == before_caddress
            && (reverted == (_tos.length == 0))
            && (reverted || ret == true)
        );
    }

    receive() external payable {}
}

